p.write_text(p.read_text()+'\ntest(\'lead maker filter offers only Olivia, Morgan and Gaby and follows original attribution across approval, age and outcome views\',()=>{\n const ctx=uiContext(),tl=ctx.TL,{V,UI,filtered}=ctx.simpleTest,old=tl.Lead(\'L_simple_old\'),recent=tl.Lead(\'L_simple_new\'),third=tl.Lead(\'L_simple_private\');old.originRep=\'u2\';old.rep=\'u3\';old.created=tl.addDays(-30);old.programStatus=\'approved\';recent.originRep=\'u1\';recent.created=tl.addDays(-2);third.originRep=\'u3\';third.created=tl.addDays(-14);\n const html=V.leads(),select=html.match(/<select[^>]*data-change="leadMaker"[^>]*>([\\s\\S]*?)<\\/select>/)[1];assert.deepEqual([...select.matchAll(/value="([^"]+)"/g)].map(m=>m[1]),[\'all\',\'u2\',\'u1\',\'u3\']);for(const name of [\'Olivia\',\'Morgan\',\'Gaby\'])assert.ok(select.includes(name));assert.ok(!select.includes(\'Efrain\'));assert.ok(!select.includes(\'Zach\'));\n UI.leadMaker=\'u2\';assert.deepEqual(Array.from(filtered(),l=>l.id),[old.id]);UI.simpleApproval=\'approved\';UI.openDays=\'14\';assert.deepEqual(Array.from(filtered(),l=>l.id),[old.id]);UI.simpleApproval=\'not-approved\';assert.equal(filtered().length,0);UI.simpleApproval=\'all\';UI.openDays=\'all\';UI.leadMaker=\'u3\';assert.deepEqual(Array.from(filtered(),l=>l.id),[third.id]);\n third.stage=\'movein\';UI.moveView=\'moved\';assert.deepEqual(Array.from(filtered(),l=>l.id),[third.id]);UI.leadMaker=\'u2\';assert.equal(filtered().length,0);UI.moveView=\'open\';UI.leadMaker=\'u1\';assert.deepEqual(Array.from(filtered(),l=>l.id),[recent.id]);UI.leadMaker=\'all\';assert.equal(filtered().length,2);\n});\n')
